"use client"

/**
 * @fileoverview Branded social login button with provider icons.
 * @author Saasflare™
 * Visual-only — renders styled buttons with provider branding.
 * No auth wiring. Wire onClick to your auth provider externally.
 * @module packages/ui/components/ui/social-button
 * @package ui
 *
 * @deprecated Use {@link SocialAuthButton} from `@saasflare/ui` instead — it
 * covers 16 providers via the brand-icon system and follows the token contract.
 *
 * @component
 * @example
 * import { SocialAuthButton } from '@saasflare/ui'; // preferred
 * <SocialAuthButton provider="google" onClick={() => signInWithGoogle()} />
 */

import { type ComponentProps } from "react"
import { cn } from "@saasflare/ui"
import { useSaasflareProps, type SaasflareComponentProps } from "@saasflare/ui"

/**
 * Providers supported by the legacy {@link SocialButton}.
 *
 * @deprecated Use the 16-member `SocialProvider` union exported from
 * `@saasflare/ui` (backed by SocialAuthButton) instead.
 */
