/**
 * Props for the SocialButton component.
 *
 * @deprecated Use {@link SocialAuthButton} (`SocialAuthButtonProps`) instead.
 */
export interface SocialButtonProps
  extends Omit<ComponentProps<"button">, "children" | keyof SaasflareComponentProps>,
    SaasflareComponentProps {
  /** Social provider to render. */
  provider: SocialButtonProvider
  /** Override the default label text. */
  label?: string
  /** Show only the icon (no text). Default: `false` */
  iconOnly?: boolean
}

/**
 * Branded social login button. Visual only — no auth wiring.
 *
 * @deprecated Use {@link SocialAuthButton} from `@saasflare/ui` instead — it
 * covers 16 providers via the brand-icon system and follows the token contract.
 *
 * @component
 * @package ui
 */
export function SocialButton({
  provider,
  label: labelOverride,
  iconOnly = false,
  className,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: SocialButtonProps) {
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })
  const config = PROVIDERS[provider]
  const displayLabel = labelOverride ?? `Continue with ${config.label}`

  return (
    <button
      type="button"
      className={cn(
        "inline-flex items-center justify-center gap-3 rounded-lg px-4 py-2.5 text-sm font-medium transition-colors",
        config.bg,
        config.fg,
        iconOnly && "px-2.5",
        className,
      )}
      aria-label={displayLabel}
      data-slot="social-button"
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
      {...props}
    >
      <svg className="size-5" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
        <path d={config.icon} />
      </svg>
      {!iconOnly && <span>{displayLabel}</span>}
    </button>
  )
}
